 internal static Offline70EconomyState Grant(string path,string receipt,uint gold,uint cash,uint item,uint count,out bool duplicate){return Apply(path,receipt,"grant",gold+":"+cash+":"+item+":"+count,delegate(Offline70EconomyState s){AddWallet(ref s.Gold,gold);AddWallet(ref s.OfflineCash,cash);if(item!=0)AddItem(s,item,count);else if(count!=0)throw new InvalidDataException("Grant item count without item");},out duplicate);}
 internal static Offline70EconomyState Purchase(string path,string receipt,uint serverCost,uint item,uint count,out bool duplicate){if(serverCost==0)throw new InvalidDataException("Offline purchase price must come from a registered server offer");return Apply(path,receipt,"offline-purchase",serverCost+":"+item+":"+count,delegate(Offline70EconomyState s){if(s.OfflineCash<serverCost)throw new InvalidDataException("Insufficient offline cash");AddItem(s,item,count);s.OfflineCash-=serverCost;},out duplicate);}
 internal static Offline70EconomyState Use(string path,string receipt,Offline70EconomyUseRequest request,long utcTicks,out bool duplicate){if(request==null||utcTicks<0||utcTicks>DateTime.MaxValue.Ticks)throw new InvalidDataException("Use request profile");Offline70EconomyItemDefinition d=Definition(request.ItemId);if(d.Kind!=1||d.HpRecovery==0&&d.MpRecovery==0&&d.HpRecoveryPercent==0&&d.MpRecoveryPercent==0&&!d.NativeStatusRecovery&&!Offline70ThrowItemsFG90.Allowed(request.ItemId,d))throw new InvalidDataException("Item use effect has not been implemented");return Apply(path,receipt,"use",request.List+":"+request.Slot+":"+request.ItemId+":"+request.InstanceChecksum+":"+request.Tick,delegate(Offline70EconomyState s){Offline70EconomyEntry e=Find(s,request.List,request.Slot);if(e==null||e.ItemId!=request.ItemId||s.Level<d.MinimumLevel||!JobMatches(d,s.Job))throw new InvalidDataException("Use ownership or level mismatch");long cooldown=(long)d.CooldownMilliseconds*TimeSpan.TicksPerMillisecond;Offline70EconomyCooldown group=null;foreach(Offline70EconomyCooldown c in s.Cooldowns)if(c.Group==d.CooldownGroup)group=c;if(cooldown>0&&group!=null&&(utcTicks<group.UtcTicks||utcTicks-group.UtcTicks<cooldown))throw new InvalidDataException("Consumable cooldown");if(e.Quantity==1)s.Inventory.Remove(e);else e.Quantity--;if(cooldown>0){if(group==null){group=new Offline70EconomyCooldown{Group=d.CooldownGroup};s.Cooldowns.Add(group);}group.UtcTicks=utcTicks;}s.LastUseUtcTicks=utcTicks;},out duplicate);}
 internal static ushort SkillBookAmount(uint item){if(item==1031)return 5;if(item==1038)return 20;throw new InvalidDataException("Unreviewed skill-point book");}
 internal static Offline70EconomyState UseSkillBook(string path,string receipt,ushort slot,uint item,out bool duplicate){ushort amount=SkillBookAmount(item);Offline70EconomyItemDefinition d=Definition(item);if(d.Kind!=1)throw new InvalidDataException("Skill book category");return Apply(path,receipt,"skill-book",slot+":"+item+":"+amount,delegate(Offline70EconomyState s){Offline70EconomyEntry owned=Find(s,0,slot);if(owned==null||owned.ItemId!=item||s.Level<d.MinimumLevel||!JobMatches(d,s.Job)||amount>10000-s.BonusSp)throw new InvalidDataException("Skill book ownership, level or SP capacity");s.BonusSp=checked((ushort)(s.BonusSp+amount));if(owned.Quantity==1)s.Inventory.Remove(owned);else owned.Quantity--;},out duplicate);}
 internal static Offline70EconomyState Move(string path,string receipt,Offline70EconomyMoveRequest r,uint nowUnix,out bool duplicate){if(r==null||r.Alternate!=0||r.Reserved!=0||r.SourceList==r.TargetList&&r.SourceSlot==r.TargetSlot)throw new InvalidDataException("Economy move routing");return Apply(path,receipt,"move",r.SourceList+":"+r.SourceSlot+":"+r.SourceItem+":"+r.Quantity+":"+r.TargetList+":"+r.TargetSlot+":"+r.TargetItem+":"+r.Tick,delegate(Offline70EconomyState s){Offline70EconomyEntry source=Find(s,r.SourceList,r.SourceSlot),target=Find(s,r.TargetList,r.TargetSlot);if(source==null||source.ItemId!=r.SourceItem||(target==null?0:target.ItemId)!=r.TargetItem)throw new InvalidDataException("Move ownership mismatch");Offline70EconomyItemDefinition d=Definition(source.ItemId);if((r.SourceList==2&&r.SourceSlot>=s.CargoSlotsFG129)||(r.TargetList==2&&r.TargetSlot>=s.CargoSlotsFG129)||!Position(r.TargetList,r.TargetSlot,d)||d.Kind==3&&r.Quantity>1)throw new InvalidDataException("Move category or count");if(r.TargetList==3&&(s.Level+(Offline70FeedbackFG129.Active(s,22,nowUnix)?5:0)<d.MinimumLevel||!JobMatches(d,s.Job)||source.ExpiresUnix!=0&&source.ExpiresUnix<=nowUnix))throw new InvalidDataException("Avatar equip requirement");if(r.TargetList==3)Offline70PetEquipmentFG103.RequirePet(s,d);if(target!=null){Offline70EconomyItemDefinition reverse=Definition(target.ItemId);if(!Position(r.SourceList,r.SourceSlot,reverse))throw new InvalidDataException("Move reverse category");if(r.SourceList==3&&(s.Level+(Offline70FeedbackFG129.Active(s,22,nowUnix)?5:0)<reverse.MinimumLevel||!JobMatches(reverse,s.Job)||target.ExpiresUnix!=0&&target.ExpiresUnix<=nowUnix))throw new InvalidDataException("Reverse equip requirement");if(r.SourceList==3)Offline70PetEquipmentFG103.RequirePet(s,reverse);}uint quantity=r.Quantity==0?source.Quantity:r.Quantity;if(quantity>source.Quantity)throw new InvalidDataException("Move excess count");if(Stackable(d)&&target!=null&&target.ItemId==source.ItemId){if(target.Quantity>d.StackLimit-quantity)throw new InvalidDataException("Move stacking capacity");target.Quantity+=quantity;source.Quantity-=quantity;if(source.Quantity==0)s.Inventory.Remove(source);return;}if(d.Kind==3||quantity==source.Quantity){if((d.Kind==4||d.Kind==8)&&r.TargetList==3)source.Sealed=false;if(target!=null&&r.SourceList==3&&(Definition(target.ItemId).Kind==4||Definition(target.ItemId).Kind==8))target.Sealed=false;source.List=r.TargetList;source.Slot=r.TargetSlot;if(target!=null){target.List=r.SourceList;target.Slot=r.SourceSlot;}return;}if(r.Quantity>source.Quantity)throw new InvalidDataException("Move excess count");if(target!=null){if(target.ItemId!=source.ItemId||target.Quantity>d.StackLimit-r.Quantity)throw new InvalidDataException("Move stacking mismatch");target.Quantity+=r.Quantity;}else{s.Inventory.Add(new Offline70EconomyEntry{List=r.TargetList,Slot=r.TargetSlot,ItemId=source.ItemId,Quantity=r.Quantity});}source.Quantity-=r.Quantity;},out duplicate);}
}
